import{_ as a,o as t,c as s,a0 as i}from"./chunks/framework.BxCN1dRw.js";const u=JSON.parse('{"title":"Quick start","description":"","frontmatter":{"docLocale":"en","counterpart":"/getting-started/quickstart"},"headers":[],"relativePath":"en/getting-started/quickstart.md","filePath":"en/getting-started/quickstart.md"}'),r={name:"en/getting-started/quickstart.md"};function n(o,e,l,d,h,p){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="quick-start" tabindex="-1">Quick start <a class="header-anchor" href="#quick-start" aria-label="Permalink to &quot;Quick start&quot;">​</a></h1><p>Core provides email/password registration, login/logout, member management, password reset, session invalidation and a real service status probe, wired as <strong>Web → generated SDK → Axum → PostgreSQL</strong>.</p><h2 id="prepare-the-tools" tabindex="-1">Prepare the tools <a class="header-anchor" href="#prepare-the-tools" aria-label="Permalink to &quot;Prepare the tools&quot;">​</a></h2><p>Use the versions pinned by the repository: Rust 1.96.0, Node 24.18.0, pnpm 11.17.0, just 1.58.0, plus a Docker / Compose setup that can run Linux containers. The versions are recorded in <code>rust-toolchain.toml</code>, <code>.node-version</code>, <code>package.json</code> and <code>.tool-versions</code>.</p><p>Every online page marks the &quot;source version&quot; in its footer — the repository commit this page was verified against. To reproduce this page exactly, check out that commit first:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/CaiZongyuan/axum-saas-template.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> axum-saas-template</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> checkout</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">footer</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> source</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> versio</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">n</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # e.g. git checkout 18710ff9b5ab</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --frozen-lockfile</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p><code>just dev</code> starts PostgreSQL/RustFS/Redis/Mailpit in Docker, runs migrations explicitly and initializes the private storage bucket, then starts the host API, Worker and Web. Web supports HMR; changing Rust sources restarts the API and the Worker. Without a <code>.env</code> file the local development settings from <code>.env.example</code> apply; copy it to <code>.env</code> first when you need to adjust anything.</p><p>Open the <a href="http://127.0.0.1:5173/register" target="_blank" rel="noreferrer">registration page</a>, enter an email, a 12–128 character password and an optional display name; a successful registration signs you in. The first successful account becomes the organization Owner, later accounts become Members. Operators should register their own Owner account before handing the deployment to regular users; no invitation or email waiting is involved.</p><p>The <a href="http://127.0.0.1:5173/system" target="_blank" rel="noreferrer">service status page</a> shows &quot;service ready&quot;, &quot;PostgreSQL connected&quot; and the current migration version; the migration history must match the current sources.</p><p>With an existing account, open the <a href="http://127.0.0.1:5173/login" target="_blank" rel="noreferrer">login page</a>. The home page signs you out and invalidates the old session; see the <a href="./../tutorials/sessions">login and sessions tutorial</a>.</p><p>Forgot-password requests can be filed from the login page; open the one-time link in <a href="http://127.0.0.1:8025" target="_blank" rel="noreferrer">Mailpit</a>. See the <a href="./../tutorials/password-reset">password reset tutorial</a>. The development mail key is stored automatically in the private <code>.secrets/development-mail-key</code> file and never enters version control.</p><p>Owners/Admins manage roles and activation from the organization members area on the home page; the last active Owner cannot be deactivated or demoted. See the <a href="./../tutorials/members">member management tutorial</a>. The background jobs entry provides safety status, attempt history and limited retries for failed jobs.</p><p>Registration, login and ordinary requests are rate limited by default; the page shows a waiting hint once the limit is reached. See <a href="./../tutorials/rate-limits">rate limits and conservative fallback</a>.</p><h2 id="save-your-first-document" tabindex="-1">Save your first document <a class="header-anchor" href="#save-your-first-document" aria-label="Permalink to &quot;Save your first document&quot;">​</a></h2><p>After signing in, open &quot;My documents&quot; → &quot;New document&quot;, enter a title and Markdown, then click &quot;Save document&quot;. Ordinary members can start right away; a personal library and Editor grant are prepared automatically on first save. The body survives a detail-page refresh, and the list reopens the document.</p><p>Creating, safe preview, title search, pagination, access isolation and reliable retries are supported; <a href="./../tutorials/edit-conflicts">editing and conflict handling</a> and <a href="./../tutorials/attachments">uploading attachments, downloading and inserting image references</a> work too. Follow-along steps: <a href="./../tutorials/personal-documents">your first Markdown document</a> and <a href="./../tutorials/search-preview">search and preview</a>.</p><p>Owners/Admins can create shared libraries from the &quot;Knowledge bases&quot; area, rename them, and grant or revoke Reader/Editor; granted members browse and write inside the library. See <a href="./../tutorials/library-grants">shared knowledge bases and grants</a>.</p><p>Open a saved document and click &quot;Export current document&quot; to produce a ZIP of the body and attachments; the page shows progress and offers the download. See <a href="./../tutorials/document-exports">document exports and background jobs</a>.</p><p>Where editing is allowed, documents or attachments can be deleted after confirmation; admins can delete whole libraries, and a background job cleans up the objects. See <a href="./../tutorials/deletion-cleanup">deletion and reliable cleanup</a>.</p><p>Once an export finishes or finally fails, check the &quot;Notifications&quot; area on the home page, mark it read or open the export detail. See <a href="./../tutorials/export-notifications">export notifications and read state</a>.</p><p>Owners/Admins can trace actual operations in &quot;Audit records&quot; by document id, action and request id. See the <a href="./../tutorials/audit-history">administrator audit tutorial</a>.</p><p>Create read-only document credentials under &quot;API Keys&quot; and read documents you may access from scripts; see the <a href="./../tutorials/api-keys">API key tutorial</a>.</p><p>Document details use the real Redis body cache while every read still verifies visibility and version against PostgreSQL; see <a href="/axum-saas-template/tutorials/versioned-cache">versioned cache and database fallback</a>.</p><p>To debug export problems, run <code>just dev-observability</code> and follow a request from the trace into the Worker, RustFS, logs and metrics; see the <a href="./../tutorials/observability">observability tutorial</a>.</p><p>The API listens on <code>127.0.0.1:3000</code> by default:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:3000/health/live</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:3000/health/ready</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:3000/api/v1/system/status</span></span></code></pre></div><p>Every response carries an <code>x-request-id</code>. The status request actually reads the migration records from PostgreSQL; it is not hard-coded presentation data.</p><h2 id="watch-a-failure-scenario" tabindex="-1">Watch a failure scenario <a class="header-anchor" href="#watch-a-failure-scenario" aria-label="Permalink to &quot;Watch a failure scenario&quot;">​</a></h2><p>Keep <code>just dev</code> running and temporarily stop the development database in another terminal:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> db-down</span></span></code></pre></div><p>Click &quot;Re-check&quot; on the service status page again. The page shows a failure hint and a request id; <code>/health/ready</code> returns <code>503</code> while <code>/health/live</code> still returns <code>200</code>.</p><p>Bring the database back and re-check:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --wait</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> postgres</span></span></code></pre></div><p><code>Ctrl+C</code> stops the development API/Worker/Web; the database, RustFS and their volumes are kept. <code>just services-down</code> stops the four dependencies without deleting data; <code>just db-down</code> stops the database alone.</p><h2 id="documentation-and-next-steps" tabindex="-1">Documentation and next steps <a class="header-anchor" href="#documentation-and-next-steps" aria-label="Permalink to &quot;Documentation and next steps&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">just</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs</span></span></code></pre></div><p>The local documentation entry is <a href="http://127.0.0.1:5174/axum-saas-template/docs/" target="_blank" rel="noreferrer">http://127.0.0.1:5174/axum-saas-template/docs/</a>. The online site and the local site are rendered from the same Markdown sources.</p><p>After copying the template, follow <a href="./publish-docs">publish the documentation site</a> to enable your own GitHub Pages; later merges to <code>main</code> are checked and published by CI.</p><p>Continue with <a href="./../tutorials/first-request">your first full-stack request</a>, the <a href="./../testing/feedback-loop">test feedback loop</a> and the <a href="./../architecture/boundaries">Core/example boundary</a>. The full roadmap is recorded in the <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/4908086f031486fa3504e25e3545970a1f62e028/docs/saas-template-architecture-spec.md" target="_blank" rel="noreferrer">architecture spec</a>.</p><h2 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h2><ul><li><strong>The database connects but ready still fails</strong>: run <code>just migrate</code>; the API never migrates automatically, and the applied migration set, success state and checksums must match the current sources.</li><li><strong>Port already in use</strong>: adjust <code>APP_BIND</code> / <code>VITE_API_PROXY</code> in <code>.env</code>; when changing the database port also adjust <code>POSTGRES_PORT</code> and <code>DATABASE_URL</code>, then restart the development entry.</li><li><strong>Rust configuration error</strong>: check the <a href="./../reference/config">generated configuration reference</a>. Errors never print database credentials.</li><li><strong>Browser requests fail</strong>: compare the request_id against the API&#39;s JSON logs; the page talks to the API through Vite&#39;s same-origin proxy, and the database URL never reaches the browser.</li></ul><hr><p>Source version：<code>4908086f0314</code> · <a href="https://github.com/CaiZongyuan/axum-saas-template/blob/4908086f031486fa3504e25e3545970a1f62e028/docs/getting-started/quickstart.en.md" target="_blank" rel="noreferrer">Page Markdown</a></p>`,43)])])}const g=a(r,[["render",n]]);export{u as __pageData,g as default};
